using KaraokeManager.DAL;namespace KaraokeManager.BUS;public sealed class KaraokeService{public KaraokeRepository Repository {get;}=new();public void ValidateService(string name,decimal price,int stock){if(string.IsNullOrWhiteSpace(name))throw new InvalidOperationException("Nhập tên dịch vụ.");if(price<0||stock<0)throw new InvalidOperationException("Giá và tồn kho không hợp lệ.");}}